"""Original v2 lesson authoring, with immutable v1 material explicitly reused.

Run this file to rebuild v2/lessons.json only. It never writes v1 resources.
"""
from __future__ import annotations
import copy
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent
LEGACY = {row['id']: row for row in json.loads((ROOT.parent / 'lessons.json').read_text())['lessons']}
PLAN = json.loads((ROOT / 'curriculum.json').read_text())
LESSONS = {}
BASE = PLAN['stage_source_url']
ORDER = PLAN['source_url']
VIGI = 'https://www.sgdsn.gouv.fr/vigipirate'
REFLEXES = 'https://www.sgdsn.gouv.fr/vigipirate/les-fiches-de-recommandations-et-de-bonnes-pratiques'
INRS = 'https://www.inrs.fr/media.html?refINRS=ED+4085'
DEONTO = 'https://www.legifrance.gouv.fr/codes/section_lc/LEGITEXT000025503132/LEGISCTA000029656370/'
CNIL = 'https://www.cnil.fr/fr/la-videosurveillance-videoprotection-au-travail'


def sec(heading, prose):
    return {'heading': heading, 'paragraphs': [p.strip() for p in prose.strip().split('\n\n') if p.strip()]}


def example(title, prose):
    return {'title': title, 'paragraphs': [p.strip() for p in prose.strip().split('\n\n') if p.strip()]}


def q(prompt, correct, wrong1, wrong2, explanation):
    return (prompt, correct, wrong1, wrong2, explanation)


def questions(ref, rows, kind):
    result = []
    for i, row in enumerate(rows, 1):
        prompt, correct, wrong1, wrong2, explanation = row
        values = [correct, wrong1, wrong2]
        shift = (i + int(ref[-2:])) % 3
        values = values[shift:] + values[:shift]
        options = [{'id': chr(97+j), 'text': value} for j, value in enumerate(values)]
        result.append({'id': ref + '-' + kind + '-' + str(i), 'prompt': prompt, 'options': options,
                       'answer': next(option['id'] for option in options if option['text'] == correct), 'explanation': explanation})
    return result


def expand(ref, sections, extra_questions):
    row = copy.deepcopy(LEGACY[ref])
    row['mode'] = 'revision_theorique'
    row['sections'].extend(sections)
    row['quiz'].extend(questions(ref, extra_questions, 'approfondissement'))
    row['source_urls'] = list(dict.fromkeys([*row['source_urls'], ORDER]))
    row['legacy_lesson_ref'] = ref
    LESSONS[ref] = row


def add(ref, title, objective, source_refs, sections, worked, columns, rows, takeaways, scenario_title, intro, decisions, quiz):
    LESSONS[ref] = {'id': ref, 'module': ref.split('-')[1], 'title': title, 'objective': objective,
        'mode': 'revision_theorique', 'source_urls': list(dict.fromkeys([BASE, ORDER, *source_refs])),
        'sections': sections, 'example': worked, 'table': {'headers': columns, 'rows': rows},
        'takeaways': takeaways, 'scenario': {'title': scenario_title, 'intro': intro,
        'steps': questions(ref, decisions, 'decision')}, 'quiz': questions(ref, quiz, 'qcu')}


