# Explicit transfer tasks give the final reading a concrete professional purpose.
TRANSFER = {
'macaps-02-05': "Pour compléter l’analyse, demandez-vous quel mot d’un compte rendu décrit réellement une action et quel mot ne traduit qu’une appréciation. Remplacer une étiquette par une menace entendue, un geste observé et un horaire permet au responsable de comprendre ce qui exigeait une protection. La précision aide ainsi à prévenir la violence sans réduire le respect dû aux personnes.",
'macaps-02-06': "Vérifiez enfin la cohérence entre deux postes : un visiteur recevrait-il la même explication à l’accueil principal et à l’entrée secondaire ? Si les réponses diffèrent sans raison liée au contexte, une clarification commune est nécessaire. Le principe d’égalité devient alors une question concrète de consigne, de transmission et d’organisation de l’équipe.",
'macaps-03-06': "Un bon contrôle de finalité peut se faire avant chaque collecte : si cette information n’était pas recueillie, la décision d’accès serait-elle encore possible ? Si oui, demandez pourquoi la procédure la réclame. La question n’autorise pas à modifier seul un dispositif, mais elle permet de signaler précisément une collecte qui paraît inutile ou insuffisamment expliquée.",
'macaps-03-07': "Pour préparer la prise de poste, comparez la mission annoncée au matériel réellement remis. Une différence doit être clarifiée avant d’être banalisée : équipement absent, document périmé ou ajout non prévu. La vérification est utile même pour un agent expérimenté, car l’ancienneté ne protège pas contre un changement de contrat, d’activité ou de règle applicable."
}
for ref, paragraph in TRANSFER.items():
    LESSONS[ref]['sections'][-1]['paragraphs'].append(paragraph)


def build():
    ordered = []
    for objective in PLAN['objectives']:
        refs = objective['lesson_refs']
        assert len(refs) * objective['lesson_minutes'] + objective.get('video_minutes', 0) + objective['assessment_minutes'] == objective['minimum_minutes'], objective['id']
        for ref in refs:
            lesson = copy.deepcopy(LESSONS[ref])
            lesson.update(objective_id=objective['id'], legal_objective=objective['title'],
                          pedagogical_scope='principal', planned_minutes=objective['lesson_minutes'])
            lesson['source_urls'] = list(dict.fromkeys(lesson['source_urls']))
            ordered.append(lesson)
    assert len(ordered) == len(LESSONS) == 28
    assert len({row['id'] for row in ordered}) == 28
    for row in ordered:
        assert len(row['quiz']) == 6, row['id']
        assert len(row['scenario']['steps']) == 3, row['id']
        for question in [*row['quiz'], *row['scenario']['steps']]:
            assert question['answer'] in {o['id'] for o in question['options']}
            assert len({o['text'] for o in question['options']}) == len(question['options'])
            assert question['explanation']
    payload = {'schema_version':2, 'version':PLAN['version'], 'reviewed_on':PLAN['reviewed_on'],
               'pedagogical_scope':'principal', 'planned_minutes':840,
               'source_reference':ORDER, 'current_distance_authorization_claimed':False,
               'lessons':ordered}
    path = ROOT / 'lessons.json'
    path.write_text(json.dumps(payload, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
    counts = {l['id']: len((' '.join(p for s in l['sections'] for p in s['paragraphs']) + ' ' + ' '.join(l['example']['paragraphs'])).split()) for l in ordered}
    print(json.dumps({'lessons':len(ordered), 'prose_words':sum(counts.values()), 'minimum_words':min(counts.values()),
                      'under_900':{ref:n for ref,n in counts.items() if n < 900}, 'output':str(path)}, ensure_ascii=False))
    return payload


if __name__ == '__main__':
    build()
